{"code":"import arclog,numpy as np
from collections import Counter
ss=arclog.load()
for i in [7,8,9]:
 p,s=ss[i-1],ss[i]; ds=arclog.diff(p.board,s.board)
 print('\nSTEP',i,s.action,'state',s.state,'levels',s.levels_completed,'frames',len(s.frames),'ndiff',len(ds),'bbox',s.diff_bbox)
 print('trans',Counter((a,b) for x,y,a,b in ds))
 # connected components of diff coords spatially via nx
 import networkx as nx
 G=nx.Graph(); coords={(x,y) for x,y,a,b in ds};G.add_nodes_from(coords)
 for x,y in coords:
  for q in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
   if q in coords:G.add_edge((x,y),q)
 comps=[]
 for cc in nx.connected_components(G):
  rec=[d for d in ds if (d[0],d[1]) in cc]
  comps.append((len(cc),(min(x for x,y in cc),min(y for x,y in cc),max(x for x,y in cc),max(y for x,y in cc)),Counter((a,b) for x,y,a,b in rec)))
 print('diff comps',sorted(comps,reverse=True))
 for c in [2,8,9]:
  print(' color',c,[(o.size,o.bbox,tuple(round(v,2) for v in o.centroid),o.hash) for o in arclog.objects(s.board,colors=c)])
 # HUD/bottom extra list
 print('hud diffs',[d for d in ds if d[1]<7 or d[1]==63])
","timeout":30}
